#include <stdio.h>
#include <stdbool.h>

int fact(int n) {
    int r = 1;
    for (int i = 1; i <= n; i++) r *= i;
    return r;
}

bool isStrong(int n) {
    int sum = 0, temp = n;
    while (temp > 0) {
        sum += fact(temp % 10);
        temp /= 10;
    }
    return sum == n;
}

int main() {
    printf("%d\n", isStrong(145));
    printf("%d\n", isStrong(123));
    return 0;
}

