#include <stdio.h>
#include <stdbool.h>

bool isStrong(int n) {
    static const int fact[] = {1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880};
    int sum = 0, temp = n;
    while (temp > 0) {
        sum += fact[temp % 10];
        temp /= 10;
    }
    return sum == n;
}

int main() {
    printf("%d\n", isStrong(145));
    printf("%d\n", isStrong(123));
    return 0;
}
